/** GUILHERME S. — V4. Public frontend, dynamic briefing, admin and customer portal. */
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>Array.from(root.querySelectorAll(q));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const digits=s=>String(s||'').replace(/\D/g,'');
const safeLink=s=>{try{const u=new URL(String(s||''));return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const mediaUrl=id=>`/.netlify/functions/media?id=${encodeURIComponent(id)}`;
const isVideo=(obj,id)=>String(obj?.mediaTypes?.[id]||'').startsWith('video/');
function externalEmbed(raw){const u=safeLink(raw);if(!u)return '';const url=new URL(u);const host=url.hostname.toLowerCase();if(['youtube.com','www.youtube.com','m.youtube.com'].includes(host)){const id=url.searchParams.get('v');if(id&&/^[a-zA-Z0-9_-]{11}$/.test(id))return `https://www.youtube-nocookie.com/embed/${id}`;}if(host==='youtu.be'){const id=url.pathname.slice(1);if(/^[a-zA-Z0-9_-]{11}$/.test(id))return `https://www.youtube-nocookie.com/embed/${id}`;}if(['vimeo.com','www.vimeo.com'].includes(host)){const id=url.pathname.split('/').filter(Boolean).pop();if(/^\d{5,14}$/.test(id))return `https://player.vimeo.com/video/${id}`;}return '';}
const icon=(name,size=19)=>{
 const all={arrow:'M5 12h14m-6-6 6 6',up:'M7 17 17 7M8 7h9v9',check:'M5 12l4 4L19 6',close:'M18 6 6 18M6 6l12 12',plus:'M12 5v14M5 12h14',play:'m9 6 10 6-10 6V6Z',lock:'M6 10h12v11H6zM9 10V7a3 3 0 0 1 6 0v3',menu:'M4 7h16M4 12h16M4 17h16',edit:'m16 5 3 3-11 11H5v-3L16 5Z',trash:'M4 7h16M10 11v7m4-7v7M6 7l1 14h10l1-14M9 7V4h6v3',upload:'M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M8.5 8h.01',chevron:'m9 18 6-6-6-6',eye:'M2 12s3.7-7 10-7 10 7 10 7-3.7 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',circle:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z',logout:'M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4m7 14 5-5-5-5m5 5H9'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${all[name]||all.arrow}"/></svg>`;
};
const DEFAULT={aboutName:'Guilherme S.',aboutRole:'Design & Motion',aboutTitle:'Criatividade com direção. Soluções visuais com propósito.',aboutBio:'Transformo ideias em experiências digitais e materiais visuais que valorizam sua marca, combinando estratégia, estética e tecnologia.',aboutImage:'',instagram:'',whatsapp:'',contactEmail:'',aboutButton:'Pedir orçamento'};
const SERVICES=[
 {id:'sites',name:'Sites',title:'Sites e experiências digitais',line:'Experiências online que valorizam sua marca.',desc:'Landing pages, sites institucionais e soluções comerciais desenvolvidas com atenção à navegação, responsividade, conversão e identidade visual.',includes:['Briefing e organização de conteúdo','Layout responsivo','Desenvolvimento e publicação','Microinterações e otimizações previstas no orçamento'],art:'sites.svg'},
 {id:'social',name:'Social',title:'Design para redes sociais',line:'Conteúdo que comunica com consistência.',desc:'Artes para redes sociais, carrosséis, campanhas e apresentações planejadas para reforçar a identidade e chamar a atenção do seu público.',includes:['Conceito visual','Artes para feed e stories','Adaptações de formato','Entrega dos materiais combinados'],art:'social.svg'},
 {id:'motion',name:'Motion',title:'Vídeos comerciais e motion',line:'Ideias ganham ritmo, narrativa e presença.',desc:'Motion graphics, vídeos comerciais e apresentações audiovisuais que transformam informações e produtos em histórias relevantes.',includes:['Roteiro conforme proposta','Narração própria ou por IA, quando contratada','Edição e animação','Trilha e acabamento final'],art:'motion.svg'},
 {id:'branding',name:'Branding',title:'Branding e identidade visual',line:'Marcas fortes começam por uma identidade clara.',desc:'Construção de universos visuais que representam posicionamento, personalidade e consistência em cada ponto de contato.',includes:['Briefing e direção criativa','Logotipo e aplicações contratadas','Paleta e tipografia','Arquivos finais combinados'],art:'branding.svg'}
];
const state={settings:{...DEFAULT},prints:[],portfolio:[],loaded:false,apiError:false,user:null,clientProjects:[],dashboard:null,activeTab:'visao',editing:null,selectedMedia:0,lightbox:null,menu:false,briefingSent:'',lastAdminError:''};
let toastTimer;
function toast(s,type='info'){const node=$('#toast');node.textContent=s;node.className=`visible ${type}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.className='',4500)}
async function api(action,data){const opts=data===undefined?{credentials:'same-origin'}:{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)};let r;
 try{r=await fetch(`/.netlify/functions/api?action=${encodeURIComponent(action)}`,opts)}catch{throw Error('Servidor indisponível. Confira o deploy e as Functions no Netlify.')}
 let o;try{o=await r.json()}catch{throw Error('Resposta inválida do servidor. Confira os logs da Function.')}
 if(!r.ok)throw Error(o.error||'Falha na solicitação.');return o;}
async function upload(file,visibility='public',clientId='',projectId=''){if(!file)throw Error('Selecione o arquivo.');if(file.size>3*1024*1024)throw Error('Limite de 3 MB por arquivo. Use vídeo externo para arquivos grandes.');const fd=new FormData();fd.append('file',file);fd.append('visibility',visibility);fd.append('clientId',clientId);fd.append('projectId',projectId);const r=await fetch('/.netlify/functions/media',{method:'POST',body:fd,credentials:'same-origin'});let data;try{data=await r.json()}catch{throw Error('Falha de envio. Confira o tamanho do arquivo e o log do Netlify.')};if(!r.ok)throw Error(data.error||'Falha no upload.');return data;}
async function loadPublic(){try{const p=await api('public');state.settings={...DEFAULT,...p.settings};state.prints=p.prints||[];state.portfolio=p.portfolio||[];state.apiError=false}catch{state.apiError=true;}state.loaded=true;render();}
function route(){return decodeURI(location.hash.slice(1)||'/').split('?')[0];}
function go(path){location.hash='#'+path;window.scrollTo({top:0,behavior:'instant'});}
const mediaTag=(m,cls='',lazy=true)=>{const id=typeof m==='string'?m:m?.id;const type=typeof m==='string'?'':m?.type||'';if(!id)return `<div class="media-placeholder ${cls}">${icon('image',36)}<small>Imagem a adicionar</small></div>`;const src=mediaUrl(id);if(type.startsWith('video/'))return `<video class="${cls}" src="${src}" playsinline controls preload="metadata"></video>`;return `<img class="${cls}" ${lazy?'loading="lazy"':''} src="${src}" alt="Mídia do projeto">`;};
function firstMedia(arr,alt='',types={}){const id=(arr||[])[0];return id?(String(types[id]||'').startsWith('video/')?`<video src="${mediaUrl(id)}" muted playsinline preload="metadata"></video>`:`<img src="${mediaUrl(id)}" loading="lazy" alt="${esc(alt)}">`):`<div class="visual-fallback">${icon('image',31)}<span>ADICIONE SUA MÍDIA</span></div>`}
function banner(){return `<header class="site-header"><div class="container header-row"><a href="#/" class="brand" aria-label="Voltar ao início"><img src="./assets/logo-guilherme-branco.png" alt="Guilherme S. Design & Motion"></a><nav class="nav desktop-nav"><a href="#/servicos">Serviços</a><a href="#/impressos">Impressos</a><a href="#/portfolio">Portfólio</a><a href="#/sobre">Sobre</a><a href="#/cliente">Área do cliente</a></nav><div class="header-end"><a class="btn btn-small btn-primary" href="#/briefing">Pedir orçamento ${icon('up',15)}</a><button class="nav-toggle" aria-label="Abrir menu" aria-expanded="${state.menu}" data-menu>${icon(state.menu?'close':'menu',24)}</button></div></div>${state.menu?`<nav class="mobile-nav"><a href="#/servicos">Serviços</a><a href="#/impressos">Impressos</a><a href="#/portfolio">Portfólio</a><a href="#/sobre">Quem eu sou</a><a href="#/cliente">Área do cliente</a><a href="#/briefing">Pedir orçamento</a></nav>`:''}</header>`;}
function footer(){return `<footer class="footer"><div class="container footer-main"><div><a class="brand" href="#/"><img src="./assets/logo-guilherme-branco.png" alt="Guilherme S."></a><p>Design com intenção. Movimento com propósito.</p></div><nav><a href="#/servicos">Serviços</a><a href="#/impressos">Impressos</a><a href="#/portfolio">Portfólio</a><a href="#/sobre">Sobre</a><a href="#/briefing">Contato</a></nav></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Guilherme S. — Design & Motion</span><span>Feito para evoluir · V4</span></div></footer>`}
function waveBanner(){const paths=Array.from({length:18},(_,i)=>{const y=30+i*4.5;return `<path d="M-30 ${y+20} C120 ${y-40+i/2} 230 ${y+90} 430 ${y+20} S720 ${y-50} 900 ${y+4} S1140 ${y+70} 1500 ${y-5}"/>`}).join('');return `<div class="wave-strip" aria-hidden="true"><svg viewBox="0 0 1400 155" preserveAspectRatio="none"><g>${paths}</g></svg></div>`;}
function showcase(){return `<div class="showcase-wrap" aria-label="Composição visual experimental do estúdio"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="showcase glass"><div class="showcase-top"><span class="tiny-led"></span> CRIAÇÃO EM MOVIMENTO <small>GS / 004</small></div><div class="showcase-center"><div class="orb-halo"></div><div class="orb orb-a"></div><div class="orb orb-b"></div><div class="orb orb-c"></div><div class="showcase-words"><small>DESIGN & MOTION</small><strong>GO<br>BEYOND.</strong><span>CRIATIVIDADE COM DIREÇÃO</span></div></div><div class="showcase-bottom"><small>WHERE IDEAS TAKE SHAPE.</small><small>✳ MADE TO CONNECT</small></div></div></div>`;}
function intro(){return `<section class="hero" id="inicio"><div class="hero-glow"></div><div class="container hero-grid"><div class="hero-copy"><h1>IDEIAS QUE<br>GANHAM FORMA.<span>MARCAS QUE MOVEM.</span></h1><p>Sites, social, motion e branding com estratégia, direção criativa e acabamento visual para marcas que querem presença — não apenas aparência.</p><div class="hero-actions"><a class="btn btn-primary" href="#/servicos">Explorar serviços <span class="circle-arrow">${icon('up',17)}</span></a><a class="btn btn-ghost" href="#/portfolio">Ver portfólio ${icon('arrow',17)}</a></div></div>${showcase()}</div></section>${waveBanner()}`}
function serviceList(){return `<section class="section services" id="servicos"><div class="container"><div class="section-label">01 / SERVIÇOS</div><div class="section-lead"><h2>Uma ideia. <span>Muitas possibilidades.</span></h2><p>Escolha o que sua marca precisa. Cada serviço tem um escopo próprio e pode ser combinado com outros.</p></div><div class="service-list">${SERVICES.map((s,i)=>`<a class="service-line" href="#/servico/${s.id}"><span class="service-index">0${i+1}</span><div><h3>${s.name}</h3><p>${s.line}</p></div><span class="service-arrow">${icon('up',21)}</span></a>`).join('')}</div><div class="inline-cta"><p>Materiais para impressão também fazem parte do estúdio.</p><a href="#/impressos">Explorar impressos ${icon('arrow',17)}</a></div></div></section>`}
const brands=[['CorelDRAW','coreldraw','CDR'],['Photoshop','adobephotoshop','Ps'],['Illustrator','adobeillustrator','Ai'],['After Effects','adobeaftereffects','Ae'],['Bridge','adobebridge','Br'],['ChatGPT','openai','GPT'],['Netlify','netlify','N'],['Canva','canva','Canva'],['GitHub','github','Git']];
function software(){return `<div class="software-field" aria-label="Ferramentas de criação utilizadas"><div class="software-grid">${brands.map(([name,slug,short])=>`<div class="software-mark" title="${name}"><img alt="" loading="lazy" src="https://cdn.jsdelivr.net/npm/simple-icons@v15/icons/${slug}.svg" onerror="this.style.display='none'"/><span>${short}</span></div>`).join('')}</div></div>`;}
function about(){const s=state.settings;return `<section class="section about" id="sobre"><div class="container">${software()}<div class="section-label">02 / QUEM EU SOU</div><div class="about-grid glass"><div class="about-photo">${s.aboutImage?`<img src="${mediaUrl(s.aboutImage)}" alt="Foto de ${esc(s.aboutName)}">`:`<img src="./assets/about-placeholder.svg" alt="Espaço reservado para a foto do designer">`}</div><div class="about-content"><span class="eyebrow">${esc(s.aboutName)} · ${esc(s.aboutRole)}</span><h2>${esc(s.aboutTitle)}</h2><p>${esc(s.aboutBio)}</p><div class="about-actions"><a href="#/briefing" class="btn btn-primary">${esc(s.aboutButton||'Pedir orçamento')} ${icon('up',17)}</a>${s.instagram?`<a class="btn btn-outline" href="${esc(safeLink(s.instagram))}" target="_blank" rel="noopener noreferrer">Seguir no Instagram ${icon('arrow',17)}</a>`:''}</div></div></div></div></section>`;}
function stepper(current=2){const labels=['Briefing','Direção criativa','Produção','Aprovação e entrega'];return `<div class="stepper">${labels.map((v,i)=>`<div class="step ${i<current?'done':i===current?'active':''}"><span class="step-dot">${i<current?icon('check',13):String(i+1)}</span><strong>${v}</strong><small>${['Entendemos a ideia','Definimos a solução','Desenvolvemos o material','Validamos e finalizamos'][i]}</small></div>`).join('')}</div>`}
function processSection(){return `<section class="section process" id="processo"><div class="container"><div class="section-label">03 / COMO FUNCIONA</div><h2>Do primeiro contato <span>à entrega.</span></h2><p class="section-sub">Etapas claras para desenvolver o seu projeto com segurança e transparência.</p>${stepper(2)}<div class="portal-teaser glass"><div><span class="eyebrow">PORTAL DO CLIENTE</span><h3>Seu projeto evolui.<br>Você acompanha.</h3><p>Acompanhe as etapas de produção, veja as prévias e registre aprovações no mesmo lugar.</p><a class="btn btn-outline" href="#/cliente">Acessar portal ${icon('up',16)}</a></div><div class="teaser-timeline"><small>ACOMPANHAMENTO ONLINE</small><p><span>✓</span> Roteiro definido</p><p><span>✓</span> Narração concluída</p><p class="active">◉ Material em produção <em>ATUAL</em></p><p>○ Aguardando aprovação</p></div></div></div></section>`}
function printTeaser(){return `<section class="section print-teaser"><div class="container"><div class="section-row"><div><div class="section-label">04 / COMUNICAÇÃO VISUAL</div><h2>Do digital <span>ao impresso.</span></h2></div><a href="#/impressos" class="text-link">Ver materiais impressos ${icon('up',17)}</a></div>${state.prints.length?`<div class="print-grid">${state.prints.slice(0,3).map(p=>printCard(p)).join('')}</div>`:`<div class="print-empty"><div class="print-mini">500 <span>UN</span></div><div><strong>Cartões, panfletos, banners e mais.</strong><p>Catálogo de materiais com acabamentos, quantidades e orçamento personalizados.</p></div><a class="btn btn-outline" href="#/impressos">Conhecer materiais ${icon('arrow',17)}</a></div>`}</div></section>`}
function home(){return `${intro()}${serviceList()}${printTeaser()}${about()}${processSection()}${briefingSection(true)}`}
function servicePage(id){const s=SERVICES.find(x=>x.id===id);if(!s)return notFound();return `<main class="page"><section class="container detail-head"><a class="back" href="#/servicos">${icon('arrow',16)} Todos os serviços</a><span class="eyebrow">SERVIÇO / ${s.name.toUpperCase()}</span><h1>${esc(s.title)}<span>.</span></h1><p>${esc(s.desc)}</p></section><div class="container detail-grid"><div class="detail-visual glass"><img src="./assets/${s.art}" alt="Conceito de ${esc(s.name)}"></div><aside class="detail-box glass"><h3>O que podemos desenvolver</h3>${s.includes.map(item=>`<p>${icon('check',16)} ${esc(item)}</p>`).join('')}<p class="detail-note">O escopo, prazo e investimento são confirmados após o briefing.</p><a class="btn btn-primary" href="#/briefing">Solicitar orçamento ${icon('up',16)}</a></aside></div></main>`}
function printCard(p){return `<a class="print-card glass" href="#/impresso/${encodeURIComponent(p.id)}"><div class="print-visual">${firstMedia(p.media,p.title,p.mediaTypes)}</div><div class="print-copy"><span class="eyebrow">MATERIAL IMPRESSO</span><h3>${esc(p.title)}</h3><p>${esc(p.description||'Material feito sob medida')}</p><div class="print-meta"><span>A partir de <strong>${esc(p.price||'sob consulta')}</strong></span><span class="round-arrow">${icon('up',18)}</span></div></div></a>`}
function printsPage(){return `<main class="page"><div class="container"><div class="section-label">CATÁLOGO / MATERIAIS IMPRESSOS</div><div class="page-lead"><h1>Qualidade em <span>cada detalhe.</span></h1><p>Conheça materiais, formatos, acabamentos e valores iniciais. Quantidades e especificações podem mudar o orçamento.</p></div>${state.prints.length?`<div class="print-grid">${state.prints.map(printCard).join('')}</div>`:`<div class="empty glass"><h3>Catálogo sendo preparado.</h3><p>Em breve você encontrará cartões de visita, panfletos, banners e outros produtos, com imagens e condições de cada modelo.</p><a class="btn btn-primary" href="#/briefing">Solicitar um impresso ${icon('up',16)}</a></div>`}</div></main>`}
function printDetail(id){const p=state.prints.find(x=>x.id===id);if(!p)return notFound();return `<main class="page"><div class="container"><a class="back" href="#/impressos">${icon('arrow',16)} Voltar aos impressos</a><div class="print-detail"><div><div class="big-media glass">${firstMedia(p.media,p.title,p.mediaTypes)}</div><div class="media-thumbs">${(p.media||[]).map((m,i)=>`<button data-open-media="${i}" data-media-group="print:${esc(id)}" aria-label="Visualizar mídia ${i+1}">${isVideo(p,m)?`<video src="${mediaUrl(m)}" muted playsinline preload="metadata"></video>`:`<img src="${mediaUrl(m)}" alt="Visualização ${i+1}" loading="lazy">`}</button>`).join('')}</div></div><div class="print-description"><div class="section-label">MATERIAL IMPRESSO</div><h1>${esc(p.title)}</h1><p>${esc(p.description)}</p><dl><dt>Valor inicial</dt><dd>${esc(p.price||'Sob consulta')}</dd><dt>Prazo de entrega</dt><dd>${esc(p.leadTime||'A combinar')}</dd><dt>Quantidades</dt><dd>${esc(p.quantities||'Sob consulta')}</dd><dt>Materiais e acabamento</dt><dd>${esc(p.material||'Conforme a proposta')}</dd></dl><a href="#/briefing" class="btn btn-primary">Solicitar orçamento ${icon('up',17)}</a></div></div></div></main>`}
function portfolioCard(p){const cover=(p.media||[])[0];return `<article class="portfolio-tile"><button data-portfolio-open="${esc(p.id)}" class="portfolio-cover glass" aria-label="Ver projeto ${esc(p.title)}">${p.kind==='site'&&!(p.media||[]).length?`<img src="./assets/sites.svg" alt="Projeto de site">`:firstMedia(p.media,p.title,p.mediaTypes)}<span class="portfolio-go">${icon('up',21)}</span></button><div class="portfolio-info"><span class="eyebrow">${esc(p.category.toUpperCase())} / ${esc(p.kind.toUpperCase())}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><button data-portfolio-open="${esc(p.id)}" class="text-link">Ver projeto ${icon('arrow',16)}</button></div></article>`}
function portfolioPage(){return `<main class="page"><div class="container"><div class="section-label">PORTFÓLIO / PROJETOS</div><div class="page-lead"><h1>Trabalhos para <span>ver de perto.</span></h1><p>Projetos selecionados em sites, social, motion e branding. Abra as peças para explorar o conteúdo; sites levam ao endereço do projeto.</p></div>${state.portfolio.length?`<div class="portfolio-grid">${state.portfolio.map(portfolioCard).join('')}</div>`:`<div class="empty glass"><h3>Os projetos estão sendo adicionados.</h3><p>A estrutura já permite apresentar sites por link e abrir imagens ou vídeos ampliados, com até várias mídias por projeto.</p></div>`}</div></main>`}
function renderLightbox(p,index=0){const media=(p.media||[]).map(m=>typeof m==='string'?m:m.id);const isSite=p.kind==='site';if(isSite&&p.website){window.open(safeLink(p.website),'_blank','noopener,noreferrer');return;}if(!media.length){if(p.videoUrl&&safeLink(p.videoUrl)){state.lightbox={title:p.title,media:[],index:0,external:p.videoUrl,type:'video'};renderOverlay();return;}toast('Este projeto ainda não tem mídias.');return;}
 state.lightbox={title:p.title,media,mediaTypes:p.mediaTypes||{},index:Math.min(Math.max(index,0),media.length-1),type:p.kind};renderOverlay();}
function renderOverlay(){const box=$('#lightbox');if(box)box.remove();if(!state.lightbox)return;const l=state.lightbox;const id=l.media[l.index];const mime=String(l.mediaTypes?.[id]||'');const type=mime==='application/pdf'?'pdf':mime.startsWith('video/')?'video':l.type==='video'?'video':'image';const el=document.createElement('div');el.id='lightbox';el.className='lightbox';el.innerHTML=`<div class="lightbox-top"><div><span>PORTFÓLIO / VISUALIZAÇÃO</span><strong>${esc(l.title)}</strong></div><button data-close-lightbox aria-label="Fechar visualização">${icon('close',24)}</button></div><div class="lightbox-body">${l.external?`<div class="external-video">${externalEmbed(l.external)?`<iframe title="Vídeo do projeto" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen src="${esc(externalEmbed(l.external))}"></iframe>`:`<video controls autoplay playsinline src="${esc(safeLink(l.external))}"></video>`}</div>`:type==='video'?`<video controls autoplay playsinline src="${mediaUrl(id)}"></video>`:type==='pdf'?`<iframe class="pdf-preview" title="Arquivo em PDF" src="${mediaUrl(id)}"></iframe>`:`<img src="${mediaUrl(id)}" alt="Mídia ampliada">`}</div><div class="lightbox-foot"><button data-slide="-1" ${l.index===0?'disabled':''}>${icon('arrow',18)} Anterior</button><span>${l.external?'VÍDEO':`${l.index+1} / ${l.media.length}`}</span><button data-slide="1" ${l.index===l.media.length-1?'disabled':''}>Próxima ${icon('arrow',18)}</button></div>`;document.body.append(el);document.body.style.overflow='hidden';}
function closeLightbox(){state.lightbox=null;$('#lightbox')?.remove();document.body.style.overflow='';}
function aboutPage(){return `<main class="page"><div class="container"><div class="page-lead"><h1>Prazer, <span>${esc(state.settings.aboutName)}.</span></h1><p>Identidade, design e movimento a serviço de projetos com personalidade.</p></div></div>${about()}</main>`}
function check(name,label){return `<label class="option"><input type="checkbox" name="interests" value="${name}"><span>${label}</span></label>`}
function briefingSection(withWrapper=false){return `<section id="briefing" class="briefing-section ${withWrapper?'home-briefing':''}"><div class="container"><div class="briefing-heading"><div class="section-label">VAMOS CONVERSAR</div><h2>Seu próximo projeto <span>começa aqui.</span></h2><p>Conte o que você precisa. O formulário funciona como um briefing inicial para montarmos uma proposta mais objetiva.</p></div><form id="briefing-form" class="briefing-form glass"><div class="form-grid"><label>Nome do cliente <input name="name" required maxlength="120" autocomplete="name" placeholder="Seu nome ou responsável"></label><label>Contato (WhatsApp) <input name="contact" type="tel" required inputmode="tel" minlength="10" placeholder="(42) 99999-9999"></label><label class="wide">Setor da empresa <input name="sector" required maxlength="150" placeholder="Ex.: comércio, saúde, serviços, educação"></label></div><div class="form-subtitle">Interesse em <small>Você pode selecionar mais de uma opção</small></div><div class="choices">${check('video','Vídeos / Motion')}${check('posts','Posts e redes sociais')}${check('impressos','Materiais impressos')}${check('sites','Sites')}</div>
 <div class="conditional" data-section="video" hidden><h3>Vídeos e motion</h3><div class="form-grid"><label>Tema do vídeo <input name="videoTheme" placeholder="O que o vídeo deve apresentar?"></label><label>Duração aproximada <input name="videoDuration" placeholder="Ex.: 30 segundos / 1 minuto"></label><fieldset class="wide"><legend>Narração</legend><label class="radio"><input type="radio" name="narration" value="propria"> Própria / fornecida</label><label class="radio"><input type="radio" name="narration" value="ia"> Voz de IA</label><label class="radio"><input type="radio" name="narration" value="sem"> Sem narração</label></fieldset></div></div>
 <div class="conditional" data-section="posts" hidden><h3>Posts e redes sociais</h3><div class="choices"><label class="option"><input type="checkbox" name="postTypes" value="carrossel"><span>Carrossel</span></label><label class="option"><input type="checkbox" name="postTypes" value="arte_unica"><span>Arte única</span></label><label class="option"><input type="checkbox" name="postTypes" value="plano_mensal"><span>Plano mensal</span></label></div></div>
 <div class="conditional" data-section="impressos" hidden><h3>Materiais impressos</h3><p>Marque os produtos desejados e especifique quantidades ou acabamento.</p><div class="print-options"><div class="print-option"><label class="option"><input type="checkbox" name="printProduct" value="cartao"><span>Cartão de visitas</span></label><div data-print="cartao" hidden><label>Quantidade <select name="cartaoQty"><option value="500">500 un.</option><option value="1000">1.000 un.</option><option value="outro">Outra quantidade</option></select></label><input name="cartaoOther" placeholder="Quantidade, caso tenha marcado outra"><input name="cartaoMaterial" placeholder="Material / acabamento desejado"></div></div><div class="print-option"><label class="option"><input type="checkbox" name="printProduct" value="panfleto"><span>Panfleto</span></label><div data-print="panfleto" hidden><label>Quantidade <select name="panfletoQty"><option value="1000">1.000 un.</option><option value="2500">2.500 un.</option><option value="outro">Outra quantidade</option></select></label><input name="panfletoOther" placeholder="Quantidade, caso tenha marcado outra"><input name="panfletoMaterial" placeholder="Material / acabamento desejado"></div></div><div class="print-option"><label class="option"><input type="checkbox" name="printProduct" value="banner"><span>Banner</span></label><div data-print="banner" hidden><input name="bannerQty" placeholder="Quantidade e dimensões"><input name="bannerMaterial" placeholder="Lona, acabamento, bastão, ilhós..."></div></div><div class="print-option"><label class="option"><input type="checkbox" name="printProduct" value="outro"><span>Outro produto</span></label><div data-print="outro" hidden><input name="outroDesc" placeholder="Qual produto?"><input name="outroQty" placeholder="Quantidade"><input name="outroMaterial" placeholder="Material / acabamento"></div></div></div></div>
 <div class="conditional" data-section="sites" hidden><h3>Sites e experiências digitais</h3><div class="form-grid"><label class="wide">Tipo de site <select name="siteType"><option value="institucional">Institucional</option><option value="captacao">Captação de clientes</option><option value="ecommerce">E-commerce</option><option value="outro">Outro</option></select></label><label class="wide">Como imagina o site e para qual finalidade será usado? <textarea name="sitePurpose" rows="4" placeholder="Objetivo, funcionalidades, público, referências..."></textarea></label></div></div>
 <label class="full-label">Informações adicionais (opcional) <textarea name="notes" rows="3" placeholder="Prazo desejado, referências, quantidade de peças ou outras informações..."></textarea></label><label class="privacy"><input type="checkbox" required name="privacy"> Autorizo o uso desses dados exclusivamente para contato e elaboração do orçamento.</label><label class="honeypot" aria-hidden="true">Não preencha este campo<input type="text" name="website_field" tabindex="-1" autocomplete="off"></label><div class="form-actions"><p>Seus dados serão encaminhados para análise. O envio não gera contratação ou cobrança automática.</p><button class="btn btn-primary" type="submit">Enviar briefing ${icon('arrow',17)}</button></div><p class="form-result" id="briefing-result" role="status"></p></form></div></section>`}
function briefingPage(){return `<main class="page">${briefingSection()}</main>`}
function clientLogin(){return `<main class="page auth-page"><div class="container auth-grid"><div><div class="section-label">PORTAL DO CLIENTE</div><h1>Seus projetos.<br><span>Seu acompanhamento.</span></h1><p>Acesse com o e-mail e a senha cadastrados. Veja o andamento da produção, abra prévias e aprove os materiais sem sair do site.</p></div><form id="login-form" class="glass login-panel"><h2>Entrar no portal</h2><label>E-mail <input name="email" type="email" required placeholder="voce@empresa.com.br" autocomplete="username"></label><label>Senha <input name="password" type="password" required minlength="8" autocomplete="current-password" placeholder="Sua senha"></label><button class="btn btn-primary" type="submit">Entrar ${icon('arrow',16)}</button><p class="fine-print">O acesso é criado pelo estúdio após a contratação. Precisa de ajuda? Entre em contato pelo formulário.</p></form></div></main>`}
function clientPage(){if(!state.user)return clientLogin();if(state.user.role==='admin')return `<main class="page"><div class="container empty"><h2>Você está conectado como administrador.</h2><a class="btn btn-primary" href="#/admin">Abrir painel ${icon('arrow',16)}</a></div></main>`;const projects=state.clientProjects||[];return `<main class="page"><div class="container"><div class="session-head"><div><div class="section-label">PORTAL DO CLIENTE</div><h1>Olá, <span>${esc(state.user.name)}</span></h1><p>Acompanhe suas entregas e aprove seus materiais.</p></div><button class="btn btn-outline" data-logout>Sair ${icon('logout',16)}</button></div>${projects.length?projects.map(clientProject).join(''):`<div class="empty glass"><h3>Nenhum projeto vinculado à sua conta ainda.</h3><p>Quando o estúdio cadastrar seu projeto, ele aparecerá aqui automaticamente.</p></div>`}<details class="password-settings glass"><summary>Segurança da conta · Alterar minha senha</summary><form id="password-form" class="form-grid"><label>Senha atual <input name="oldPassword" type="password" autocomplete="current-password" required minlength="8"></label><label>Nova senha <input name="newPassword" type="password" autocomplete="new-password" required minlength="8"></label><button class="btn btn-outline" type="submit">Atualizar senha ${icon('check',16)}</button></form></details></div></main>`}
function clientProject(p){const latest=p.versions?.at(-1);return `<article class="client-project glass"><div class="client-project-top"><div><small>PROJETO ${esc((p.type||'CRIATIVO').toUpperCase())}</small><h2>${esc(p.title)}</h2><span class="pill">${statusLabel(p.status)}</span></div><div><small>PREVISÃO DE ENTREGA</small><strong>${p.dueDate?new Date(p.dueDate+'T12:00:00').toLocaleDateString('pt-BR'):'A combinar'}</strong></div></div><p>${esc(p.description||'Acompanhe as etapas do projeto abaixo.')}</p><div class="client-steps">${(p.stages||[]).map((s,i)=>`<div class="client-step ${i<p.currentStage?'done':i===p.currentStage?'current':''}"><span>${i<p.currentStage?'✓':i+1}</span>${esc(s)}</div>`).join('')}</div>${latest?`<div class="review-box"><div class="review-head"><strong>Prévia ${latest.number}</strong><span>${new Date(latest.createdAt).toLocaleDateString('pt-BR')}</span></div><p>${esc(latest.note)}</p><div class="review-gallery">${(latest.media||[]).map((m,i)=>`<div class="review-file"><button type="button" data-private-preview="${esc(p.id)}" data-private-index="${i}">${icon('eye',15)} Abrir material ${i+1}</button></div>`).join('')}${latest.link?`<a href="${esc(safeLink(latest.link))}" target="_blank" rel="noopener noreferrer" class="btn btn-outline">Abrir vídeo externo ${icon('up',15)}</a>`:''}</div>${p.status==='aguardando_aprovacao'?`<form class="review-form" data-review="${esc(p.id)}" data-version="${esc(latest.id)}"><div class="review-choices"><label class="radio"><input type="radio" name="decision" value="approved" required> Aprovar versão</label><label class="radio"><input type="radio" name="decision" value="changes" required> Solicitar ajustes</label></div><div class="form-grid"><label>Momento do vídeo (se aplicável) <input name="timecode" placeholder="Ex.: 00:15"></label><label class="wide">Comentários / ajustes <textarea name="comment" rows="3" placeholder="Descreva os ajustes ou deixe uma observação."></textarea></label></div><button type="submit" class="btn btn-primary">Registrar minha decisão ${icon('check',16)}</button></form>`:`<p class="notice">${p.status==='aprovado'?'Você aprovou esta versão. Obrigado!':p.status==='ajustes'?'Seus ajustes foram recebidos. Aguarde uma nova prévia.':'A prévia está disponível para consulta.'}</p>`}</div>`:''}<details class="history"><summary>Histórico de atualizações</summary>${(p.history||[]).slice().reverse().map(e=>`<p><small>${new Date(e.at).toLocaleString('pt-BR')}</small> ${esc(e.event)}</p>`).join('')}</details></article>`}
function statusLabel(s){return ({novo:'Novo',em_producao:'Em produção',aguardando_aprovacao:'Aguardando aprovação',ajustes:'Ajustes solicitados',aprovado:'Aprovado',finalizado:'Finalizado'})[s]||s;}
function notFound(){return `<main class="page"><div class="container empty"><h1>Não encontramos esta página.</h1><a href="#/" class="btn btn-primary">Voltar ao início</a></div></main>`}
const ADMIN_TABS=[['visao','Visão geral'],['briefings','Briefings'],['portfolio','Portfólio'],['impressos','Impressos'],['clientes','Clientes'],['projetos','Projetos'],['biografia','Biografia']];
const makeEdit=(kind,item)=>{state.editing={kind,data:structuredClone(item||{})};state.versionMedia=[];render();};
function adminPage(){if(!state.user)return clientLogin();if(state.user.role!=='admin')return `<main class="page"><div class="container empty">Você não possui acesso administrativo.</div></main>`;const d=state.dashboard;if(!d)return `<main class="page"><div class="container empty">Carregando painel administrativo...</div></main>`;const tab=state.activeTab;return `<main class="admin-page"><div class="container"><div class="admin-head"><div><div class="section-label">GESTÃO DO ESTÚDIO / V4</div><h1>Seu painel <span>de controle.</span></h1><p>Produtos, projetos, arquivos, briefing e clientes em um único lugar.</p></div><button class="btn btn-outline" data-logout>Sair ${icon('logout',16)}</button></div><div class="admin-layout"><nav class="admin-nav" aria-label="Seções do painel">${ADMIN_TABS.map(([id,name])=>`<button class="admin-tab ${tab===id?'current':''}" data-tab="${id}">${name}</button>`).join('')}</nav><section class="admin-content">${tab==='visao'?adminOverview(d):tab==='briefings'?adminBriefings(d):tab==='portfolio'?adminCollection('portfolio',d.portfolio):tab==='impressos'?adminCollection('print',d.prints):tab==='clientes'?adminCollection('client',d.clients):tab==='projetos'?adminCollection('project',d.projects):adminBiography(d)}</section></div></div></main>`;}
function adminOverview(d){const counts=[['Briefings recebidos',d.briefings.length],['Projetos',d.projects.length],['Clientes',d.clients.length],['Materiais impressos',d.prints.length],['Projetos no portfólio',d.portfolio.length]];return `<h2>Visão geral</h2><div class="stats">${counts.map(([l,v])=>`<div class="glass stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="glass admin-block"><h3>Pendências</h3>${d.projects.filter(x=>x.status==='aguardando_aprovacao'||x.status==='ajustes').length?d.projects.filter(x=>x.status==='aguardando_aprovacao'||x.status==='ajustes').map(p=>`<div class="list-row"><span>${esc(p.title)}</span><small>${statusLabel(p.status)}</small></div>`).join(''):'<p>Sem projetos aguardando aprovação ou ajustes.</p>'}</div><div class="glass admin-block"><h3>Primeiros passos</h3><p>Cadastre os materiais impressos, adicione trabalhos reais, personalize sua biografia e crie clientes e projetos com acompanhamento e aprovação.</p></div>`}
function briefingDetails(b){const prints=b.prints||{};return `<div class="brief-details"><p><b>Cliente:</b> ${esc(b.name)}</p><p><b>Contato:</b> ${esc(b.contact)}</p><p><b>Setor:</b> ${esc(b.sector)}</p><p><b>Interesses:</b> ${(b.interests||[]).map(esc).join(', ')}</p>${b.interests?.includes('video')?`<p><b>Vídeo:</b> ${esc(b.video?.theme||'Não informado')} · ${esc(b.video?.duration||'Duração a combinar')} · Narração ${esc(b.video?.narration||'não definida')}</p>`:''}${b.interests?.includes('posts')?`<p><b>Posts:</b> ${(b.posts||[]).map(esc).join(', ')||'A definir'}</p>`:''}${b.interests?.includes('impressos')?`<p><b>Impressos:</b></p>${Object.entries(prints).filter(([,x])=>x.selected).map(([name,x])=>`<p>${esc(name)} — ${esc(x.quantity)} — ${esc(x.material)} — ${esc(x.description)}</p>`).join('')}`:''}${b.interests?.includes('sites')?`<p><b>Site:</b> ${esc(b.sites?.kind)} — ${esc(b.sites?.purpose)}</p>`:''}<p><b>Observações:</b> ${esc(b.notes||'Nenhuma')}</p></div>`}
function adminBriefings(d){return `<div class="admin-section-title"><div><h2>Briefings recebidos</h2><p>Solicitações enviadas pelo formulário público.</p></div></div>${d.briefings.length?d.briefings.map(b=>`<details class="glass brief-card"><summary><span><strong>${esc(b.name)}</strong><small>${esc(b.sector)} · ${new Date(b.createdAt).toLocaleString('pt-BR')}</small></span><span class="pill">${esc(b.status)}</span></summary>${briefingDetails(b)}<div class="admin-actions"><select data-brief-status="${esc(b.id)}"><option value="novo" ${b.status==='novo'?'selected':''}>Novo</option><option value="contatado" ${b.status==='contatado'?'selected':''}>Contatado</option><option value="em_orcamento" ${b.status==='em_orcamento'?'selected':''}>Em orçamento</option><option value="concluido" ${b.status==='concluido'?'selected':''}>Concluído</option></select><button class="btn btn-outline btn-small" data-delete="briefing:${esc(b.id)}">Excluir</button></div></details>`).join(''):'<div class="empty glass">Nenhum briefing recebido ainda.</div>'}`}
const collection=(kind,d)=>({portfolio:d.portfolio,print:d.prints,client:d.clients,project:d.projects})[kind]||[];
function adminCollection(kind,items){const names={portfolio:'Projetos do portfólio',print:'Materiais impressos',client:'Clientes cadastrados',project:'Projetos dos clientes'};const buttonNames={portfolio:'Novo trabalho',print:'Novo impresso',client:'Novo cliente',project:'Novo projeto'};return `<div class="admin-section-title"><div><h2>${names[kind]}</h2><p>${kind==='print'?'Cadastre materiais, preços, acabamentos, prazos e até três mídias por produto.':kind==='portfolio'?'Adicione sites por link, imagens e vídeos para abrir em tela expandida.':kind==='project'?'Atualize as etapas e publique prévias para aprovação.':'Crie credenciais individuais por e-mail e senha.'}</p></div><button class="btn btn-primary btn-small" data-new="${kind}">${icon('plus',16)} ${buttonNames[kind]}</button></div><div class="admin-items">${items.length?items.map(x=>`<div class="glass admin-item"><div>${kind==='print'||kind==='portfolio'?`<div class="admin-thumb">${firstMedia(x.media,x.title,x.mediaTypes)}</div>`:''}<strong>${esc(x.title||x.name)}</strong><small>${esc(x.price||x.email||statusLabel(x.status)||'')}</small></div><div class="admin-actions"><button class="btn btn-outline btn-small" data-edit="${kind}:${esc(x.id)}">Editar</button><button class="icon-button" title="Excluir" aria-label="Excluir" data-delete="${kind}:${esc(x.id)}">${icon('trash',17)}</button></div></div>`).join(''):'<div class="empty glass">Ainda não há registros nesta seção.</div>'}</div>${state.editing?.kind===kind?renderEditor(kind,state.editing.data):''}`}
function input(name,title,value='',opts=''){return `<label>${title}<input name="${name}" value="${esc(value)}" ${opts}></label>`}
function textarea(name,title,value='',rows=3){return `<label class="wide">${title}<textarea name="${name}" rows="${rows}">${esc(value)}</textarea></label>`}
function imageSlots(data,kind){const ids=data.media||[];const max=kind==='print'?3:10;return `<div class="editor-files"><h4>Mídias (${ids.length}/${max})</h4><p>${kind==='print'?'Use até três arquivos: frente, verso e um acabamento em GIF ou vídeo curto. Prefira imagens quadradas (1:1).':'Imagens e vídeos curtos podem ser abertos em tela expandida. Para vídeos grandes, use link externo.'}</p><div class="editor-media-grid">${ids.map((id,i)=>`<div class="media-slot">${data.mediaTypes?.[id]?.startsWith('video/')?`<video src="${mediaUrl(id)}" muted playsinline controls></video>`:`<img src="${mediaUrl(id)}" alt="Mídia ${i+1}">`}<small>${['Frente','Verso','Extra'][i]||`Mídia ${i+1}`}</small><button type="button" data-media-remove="${i}" aria-label="Remover mídia">×</button></div>`).join('')}${ids.length<max?`<label class="upload-box">${icon('upload',22)}<span>Adicionar mídia</span><small>PNG, JPG, WebP, GIF, MP4 ou WebM até 3 MB</small><input type="file" data-media-upload="${kind}" accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm"></label>`:''}</div></div>`}
function renderEditor(kind,d){const exists=!!d.id;let body='';
 if(kind==='print'){body=`<div class="form-grid">${input('title','Nome do material',d.title,'required')}${input('price','Valor a partir de',d.price,'placeholder="R$ 00,00"')}${input('leadTime','Prazo de entrega',d.leadTime,'placeholder="Ex.: 5 a 7 dias úteis"')}${input('quantities','Quantidades disponíveis',d.quantities,'placeholder="Ex.: 500 / 1000 un."')}${input('material','Material / acabamento',d.material,'placeholder="Ex.: Couchê 300g, laminação"')}${textarea('description','Descrição',d.description,4)}</div>${imageSlots(d,kind)}<div class="checkbox-row"><label><input type="checkbox" name="featured" ${d.featured?'checked':''}> Em destaque</label><label><input type="checkbox" name="hidden" ${d.hidden?'checked':''}> Ocultar no site</label></div>`}
 if(kind==='portfolio'){body=`<div class="form-grid">${input('title','Título do projeto',d.title,'required')}<label>Categoria<select name="category">${['sites','social','motion','branding'].map(v=>`<option value="${v}" ${d.category===v?'selected':''}>${v.toUpperCase()}</option>`).join('')}</select></label><label>Tipo<select name="kind"><option value="site" ${d.kind==='site'?'selected':''}>Site / Link externo</option><option value="artes" ${d.kind==='artes'?'selected':''}>Artes / Galeria</option><option value="video" ${d.kind==='video'?'selected':''}>Vídeo</option></select></label>${input('website','Link do site (para tipo Site)',d.website,'placeholder="https://..."')}${input('videoUrl','URL de vídeo externo (opcional)',d.videoUrl,'placeholder="https://..."')}${textarea('description','Descrição do trabalho',d.description,4)}</div>${imageSlots(d,kind)}<div class="checkbox-row"><label><input type="checkbox" name="featured" ${d.featured?'checked':''}> Em destaque</label><label><input type="checkbox" name="hidden" ${d.hidden?'checked':''}> Ocultar no site</label></div>`}
 if(kind==='client'){body=`<div class="form-grid">${input('name','Nome do cliente',d.name,'required')}${input('email','E-mail de acesso',d.email,'type="email" required')}${input('phone','Telefone (opcional)',d.phone,'inputmode="tel"')}${input('password',exists?'Nova senha (deixe vazio para manter)':'Senha inicial (mín. 8 caracteres)','',exists?'type="password" autocomplete="new-password"':'required minlength="8" type="password" autocomplete="new-password"')}</div><div class="checkbox-row"><label><input type="checkbox" name="disabled" ${d.disabled?'checked':''}> Bloquear acesso deste cliente</label></div><p class="fine-print">As senhas são processadas e armazenadas como hash no servidor. Oriente o cliente a trocar a senha por uma escolhida por ele quando essa função estiver disponível.</p>`}
 if(kind==='project'){body=`<div class="form-grid">${input('title','Título do projeto',d.title,'required')}<label>Cliente<select name="clientId" required><option value="">Selecione...</option>${(state.dashboard?.clients||[]).map(c=>`<option value="${esc(c.id)}" ${d.clientId===c.id?'selected':''}>${esc(c.name)} (${esc(c.email)})</option>`).join('')}</select></label>${input('type','Tipo de serviço',d.type,'placeholder="Ex.: Vídeo comercial"')}${input('dueDate','Previsão de entrega',d.dueDate,'type="date"')}<label>Status<select name="status">${['novo','em_producao','aguardando_aprovacao','ajustes','aprovado','finalizado'].map(v=>`<option value="${v}" ${d.status===v?'selected':''}>${statusLabel(v)}</option>`).join('')}</select></label><label>Etapa atual (posição, iniciando em 1) <input type="number" min="1" name="currentStage" value="${(d.currentStage||0)+1}" required></label>${textarea('stages','Etapas (uma por linha)',(d.stages||['Briefing','Roteiro','Produção','Aguardando aprovação','Entrega']).join('\n'),5)}${textarea('description','Descrição interna / orientação ao cliente',d.description,4)}</div>${d.id?`<div class="publish-area"><h3>Enviar prévia para aprovação</h3><p>Os arquivos desta área são privados: somente você e o cliente deste projeto podem acessá-los.</p><div class="upload-private"><label>${icon('upload',20)} Anexar foto, vídeo curto ou PDF (até 3 MB)<input type="file" data-private-upload accept="image/png,image/jpeg,image/webp,image/gif,video/mp4,video/webm,application/pdf"></label><div class="private-file-list">${(state.versionMedia||[]).map(m=>`<span>${icon('check',14)} ${esc(m.name)} <button type="button" data-remove-version-media="${esc(m.id)}">×</button></span>`).join('')}</div></div>${input('previewLink','Link de vídeo externo (opcional)','','placeholder="https://..."')}${textarea('versionNote','Mensagem ao cliente sobre esta versão','',2)}<button type="button" class="btn btn-outline" id="publish-version">Publicar prévia ${icon('up',16)}</button></div><div class="project-history"><h3>Versões e aprovações</h3>${(d.versions||[]).slice().reverse().map(v=>`<div class="history-item"><strong>Versão ${v.number}</strong><small>${new Date(v.createdAt).toLocaleString('pt-BR')}</small><p>${esc(v.note)}</p></div>`).join('')}${(d.reviews||[]).slice().reverse().map(r=>`<div class="history-item"><strong>${r.decision==='approved'?'Aprovado':'Alterações solicitadas'}</strong><small>${new Date(r.at).toLocaleString('pt-BR')}</small><p>${esc(r.comment)}</p></div>`).join('')}</div>`:'<p class="notice">Salve o projeto primeiro para habilitar o envio das prévias privadas.</p>'}`}
 return `<div class="glass editor-panel"><div class="editor-head"><h3>${exists?'Editar':'Adicionar'} ${({print:'material',portfolio:'trabalho',client:'cliente',project:'projeto'})[kind]}</h3><button type="button" class="icon-button" data-cancel-edit>${icon('close',21)}</button></div><form id="editor-form" data-kind="${kind}">${body}<div class="editor-buttons"><button type="submit" class="btn btn-primary">Salvar ${icon('check',16)}</button><button type="button" class="btn btn-outline" data-cancel-edit>Cancelar</button></div></form></div>`}
function adminBiography(d){const s=state.editing?.kind==='settings'?state.editing.data:d.settings;return `<div class="admin-section-title"><div><h2>Biografia e contatos</h2><p>Controle a sua foto, apresentação, Instagram, botão principal e WhatsApp, sem editar código.</p></div></div><div class="glass editor-panel"><form id="settings-form"><div class="form-grid">${input('aboutName','Nome ou assinatura',s.aboutName,'required')}${input('aboutRole','Cargo / especialidades',s.aboutRole)}${input('aboutTitle','Título da biografia',s.aboutTitle)}${input('aboutButton','Texto do botão principal',s.aboutButton)}${input('instagram','Link do Instagram',s.instagram,'placeholder="https://instagram.com/..."')}${input('whatsapp','WhatsApp comercial',s.whatsapp,'inputmode="tel"')}${input('contactEmail','E-mail comercial',s.contactEmail,'type="email"')}${textarea('aboutBio','Biografia',s.aboutBio,6)}</div><div class="bio-upload"><div class="bio-mini">${s.aboutImage?`<img src="${mediaUrl(s.aboutImage)}" alt="Foto atual">`:'<img src="./assets/about-placeholder.svg" alt="Foto ainda não enviada">'}</div><label class="upload-box">${icon('upload',21)} Enviar foto (PNG / JPG / WebP)<input type="file" id="bio-file" accept="image/png,image/jpeg,image/webp"></label></div><button type="submit" class="btn btn-primary">Salvar biografia e contatos ${icon('check',16)}</button></form></div>`}
async function refreshDashboard(){state.dashboard=(await api('dashboard'));}
async function refreshClient(){const r=await api('clientData');state.clientProjects=r.projects||[];}
async function getAuth(){try{const r=await api('me');state.user=r.user;if(state.user.role==='admin'&&!state.dashboard)await refreshDashboard();if(state.user.role==='client')await refreshClient()}catch{state.user=null;}}
function currentFormDraft(){const f=$('#editor-form');if(!f||!state.editing)return;const data=new FormData(f);const d=state.editing.data;for(const [key,val] of data){if(key==='stages')d.stages=String(val).split('\n').map(x=>x.trim()).filter(Boolean);else if(key==='currentStage')d.currentStage=Math.max(Number(val)-1,0);else if(key!=='password')d[key]=val;}if(data.get('password'))d.password=data.get('password');for(const c of ['featured','hidden','disabled'])d[c]=data.has(c);}
async function saveEditor(form){currentFormDraft();const {kind,data}=state.editing;const actions={portfolio:'savePortfolio',print:'savePrint',client:'saveClient',project:'saveProject'};const x=await api(actions[kind],data);toast('Registro salvo no Netlify.','success');await refreshDashboard();state.editing={kind,data:x.item};render();}
function mediaForLightbox(type,id,media){const p={title:type==='print'?'Material impresso':'Projeto',kind:type==='print'?'print':'artes',media};renderLightbox(p,Math.max(0,media.indexOf(id)));}
function adminMediaUpload(e){const field=e.target;const file=field.files?.[0];if(!file||!state.editing)return;currentFormDraft();const {kind,data}=state.editing;upload(file).then(r=>{data.media=data.media||[];data.mediaTypes=data.mediaTypes||{};if(data.media.length>=(kind==='print'?3:10))throw Error('Limite de arquivos atingido.');data.media.push(r.id);data.mediaTypes[r.id]=r.mime;toast('Arquivo enviado. Clique em Salvar para vincular ao produto.','success');render()}).catch(err=>toast(err.message,'error'));}
function uploadPrivateFile(e){const file=e.target.files?.[0];const p=state.editing?.data;if(!file||!p?.id)return;upload(file,'private',p.clientId,p.id).then(r=>{state.versionMedia.push(r);toast('Prévia privada enviada.','success');render()}).catch(err=>toast(err.message,'error'))}
async function publishVersion(){const p=state.editing?.data;if(!p?.id)return;const link=$('[name="previewLink"]')?.value||'';const note=$('[name="versionNote"]')?.value||'';const x=await api('publishVersion',{projectId:p.id,media:(state.versionMedia||[]).map(m=>m.id),mediaTypes:Object.fromEntries((state.versionMedia||[]).map(m=>[m.id,m.mime])),link,note});state.versionMedia=[];toast('Prévia publicada para o cliente!','success');await refreshDashboard();state.editing={kind:'project',data:x.item};render();}
async function saveSettings(form){const data=Object.fromEntries(new FormData(form));if(state.editing?.kind==='settings'&&state.editing.data.aboutImage)data.aboutImage=state.editing.data.aboutImage;else data.aboutImage=state.dashboard.settings.aboutImage;await api('saveSettings',data);await refreshDashboard();state.settings={...DEFAULT,...state.dashboard.settings};state.editing=null;toast('Biografia atualizada no servidor.','success');render();}
function getPrintBrief(fd){const all={};for(const name of ['cartao','panfleto','banner','outro']){const selected=fd.getAll('printProduct').includes(name);const other=fd.get(name+'Other');const qty=fd.get(name+'Qty');all[name]={selected,quantity:qty==='outro'?String(other||''):String(qty||''),material:String(fd.get(name+'Material')||''),description:String(fd.get(name+'Desc')||'')}}return all;}
async function sendBriefing(form){const fd=new FormData(form);const interests=fd.getAll('interests');if(!interests.length){toast('Selecione pelo menos uma área de interesse.','error');return;}const data={name:fd.get('name'),contact:fd.get('contact'),sector:fd.get('sector'),interests,video:{theme:fd.get('videoTheme'),duration:fd.get('videoDuration'),narration:fd.get('narration')},posts:fd.getAll('postTypes'),prints:getPrintBrief(fd),sites:{kind:fd.get('siteType'),purpose:fd.get('sitePurpose')},notes:fd.get('notes'),website_field:fd.get('website_field')};const result=$('#briefing-result');result.textContent='Enviando briefing...';try{const response=await api('briefing',data);form.reset();updateBriefVisibility();result.innerHTML=`<strong>Briefing enviado!</strong> Referência: ${esc(response.reference)}. Entraremos em contato pelo número informado.`;toast('Briefing recebido com sucesso.','success')}catch(e){result.textContent=e.message;toast(e.message,'error')}}
function updateBriefVisibility(){const form=$('#briefing-form');if(!form)return;const values=new FormData(form).getAll('interests');$$('[data-section]',form).forEach(el=>el.hidden=!values.includes(el.dataset.section));const prints=new FormData(form).getAll('printProduct');$$('[data-print]',form).forEach(el=>el.hidden=!prints.includes(el.dataset.print))}
function render(){const path=route();if(!state.loaded){$('#app').innerHTML='<div class="loading">Preparando portfólio...</div>';return;}
 let body='';if(path==='/'||path==='')body=home();else if(path==='/servicos')body=`<main class="page">${serviceList()}</main>`;else if(path.startsWith('/servico/'))body=servicePage(path.split('/')[2]);else if(path==='/impressos')body=printsPage();else if(path.startsWith('/impresso/'))body=printDetail(path.split('/')[2]);else if(path==='/portfolio')body=portfolioPage();else if(path==='/sobre')body=aboutPage();else if(path==='/briefing')body=briefingPage();else if(path==='/cliente')body=clientPage();else if(path.startsWith('/admin'))body=adminPage();else body=notFound();$('#app').innerHTML=`${banner()}${body}${footer()}`;document.title=`${path==='/portfolio'?'Portfólio | ':path.startsWith('/admin')?'Admin | ':path==='/cliente'?'Portal do Cliente | ':''}Guilherme S. — Design & Motion`;}
function scrollTop(){window.scrollTo({top:0,behavior:'instant'})}
window.addEventListener('hashchange',async()=>{closeLightbox();state.menu=false;scrollTop();if((route().startsWith('/admin')||route()==='/cliente')&&!state.user)await getAuth();else if(route().startsWith('/admin')&&state.user?.role==='admin'&&!state.dashboard)await refreshDashboard();render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeLightbox();if(state.lightbox&&e.key==='ArrowRight'&&state.lightbox.index<state.lightbox.media.length-1){state.lightbox.index++;renderOverlay()}if(state.lightbox&&e.key==='ArrowLeft'&&state.lightbox.index>0){state.lightbox.index--;renderOverlay()}});
document.addEventListener('click',async e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.hasAttribute('data-menu')){state.menu=!state.menu;render();return;}
 if(el.hasAttribute('data-close-lightbox')){closeLightbox();return;}
 if(el.dataset.slide){state.lightbox.index=Math.max(0,Math.min(state.lightbox.media.length-1,state.lightbox.index+Number(el.dataset.slide)));renderOverlay();return;}
 if(el.dataset.privatePreview){const project=state.clientProjects.find(p=>p.id===el.dataset.privatePreview);const latest=project?.versions?.at(-1);if(latest)renderLightbox({title:project.title+' — Prévia '+latest.number,media:latest.media,mediaTypes:latest.mediaTypes,kind:'artes'},Number(el.dataset.privateIndex||0));return;}
 if(el.dataset.portfolioOpen){const p=state.portfolio.find(x=>x.id===el.dataset.portfolioOpen);if(p){if(p.kind==='site'&&p.website)window.open(safeLink(p.website),'_blank','noopener,noreferrer');else renderLightbox({...p,mediaTypes:p.mediaTypes},0)}return;}
 if(el.dataset.openMedia!==undefined){const [kind,id]=String(el.dataset.mediaGroup||'').split(':');const p=state.prints.find(x=>x.id===id);if(p){renderLightbox({title:p.title,media:p.media,mediaTypes:p.mediaTypes,kind:'print'},Number(el.dataset.openMedia))}return;}
 if(el.hasAttribute('data-logout')){try{await api('logout',{})}catch{}state.user=null;state.dashboard=null;state.clientProjects=[];toast('Você saiu da sua conta.');go('/cliente');render();return;}
 if(el.dataset.tab){state.activeTab=el.dataset.tab;state.editing=null;render();return;}
 if(el.dataset.new){makeEdit(el.dataset.new,{});return;}
 if(el.dataset.edit){const [kind,id]=el.dataset.edit.split(':');const data=collection(kind,state.dashboard).find(x=>x.id===id);if(data)makeEdit(kind,data);return;}
 if(el.hasAttribute('data-cancel-edit')){state.editing=null;render();return;}
 if(el.dataset.mediaRemove!==undefined){currentFormDraft();const d=state.editing.data;d.media.splice(Number(el.dataset.mediaRemove),1);render();return;}
 if(el.dataset.removeVersionMedia){state.versionMedia=state.versionMedia.filter(x=>x.id!==el.dataset.removeVersionMedia);render();return;}
 if(el.id==='publish-version'){el.disabled=true;try{await publishVersion()}catch(err){toast(err.message,'error')}finally{el.disabled=false}return;}
 if(el.dataset.delete){const [kind,id]=el.dataset.delete.split(':');if(!confirm('Excluir este registro? Esta ação não pode ser desfeita.'))return;try{await api('remove',{type:kind,id});await refreshDashboard();state.editing=null;render();toast('Registro excluído.','success')}catch(err){toast(err.message,'error')}return;}
});
document.addEventListener('change',async e=>{
 if(e.target.closest('#briefing-form')){updateBriefVisibility();return;}
 if(e.target.dataset.mediaUpload){adminMediaUpload(e);return;}
 if(e.target.hasAttribute('data-private-upload')){uploadPrivateFile(e);return;}
 if(e.target.id==='bio-file'){const file=e.target.files?.[0];if(!file)return;const draft=Object.fromEntries(new FormData($('#settings-form')));try{const r=await upload(file);state.editing={kind:'settings',data:{...state.dashboard.settings,...draft,aboutImage:r.id}};render();toast('Foto enviada. Agora clique em Salvar biografia.','success')}catch(err){toast(err.message,'error')}return;}
 if(e.target.dataset.briefStatus){try{await api('updateBriefing',{id:e.target.dataset.briefStatus,status:e.target.value});await refreshDashboard();render();toast('Situação atualizada.','success')}catch(err){toast(err.message,'error')}return;}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['briefing-form','login-form','editor-form','settings-form','password-form'].includes(form.id)&&!form.matches('[data-review]'))return;e.preventDefault();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;
 try{
  if(form.id==='briefing-form')await sendBriefing(form);
  else if(form.id==='login-form'){const f=new FormData(form);const res=await api('login',{email:f.get('email'),password:f.get('password')});state.user=res.user;if(state.user.role==='admin'){await refreshDashboard();state.activeTab='visao';go('/admin')}else{await refreshClient();go('/cliente')}render();toast('Acesso autorizado.','success')}
  else if(form.id==='editor-form')await saveEditor(form);
  else if(form.id==='settings-form')await saveSettings(form);
  else if(form.id==='password-form'){const f=new FormData(form);await api('changePassword',{oldPassword:f.get('oldPassword'),newPassword:f.get('newPassword')});form.reset();toast('Senha atualizada com sucesso.','success')}
  else if(form.matches('[data-review]')){const f=new FormData(form);const res=await api('review',{projectId:form.dataset.review,versionId:form.dataset.version,decision:f.get('decision'),comment:f.get('comment'),timecode:f.get('timecode')});await refreshClient();render();toast('Sua resposta foi registrada.','success')}
 }catch(err){toast(err.message,'error');if(form.id==='briefing-form')$('#briefing-result').textContent=err.message}finally{if(btn&&document.contains(btn))btn.disabled=false}
});
(async()=>{await loadPublic();if(location.hash.startsWith('#/admin')||location.hash.startsWith('#/cliente')){await getAuth();render()}})();
